import{_ as e,c as i,o as l,ae as o}from"./chunks/framework.DNEoaTf_.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"en/changelog.md","filePath":"en/changelog.md"}'),t={name:"en/changelog.md"};function r(n,a,s,u,h,c){return l(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>This page contains the change history for YouTube Watch Thumbnails.</p><p>For detailed changelog, see <a href="https://github.com/mosunset/youtube_watch_thumbnails/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG.md on GitHub</a>.</p><h2 id="v1-0-0-2024-11-24" tabindex="-1">v1.0.0 (2024-11-24) <a class="header-anchor" href="#v1-0-0-2024-11-24" aria-label="Permalink to &quot;v1.0.0 (2024-11-24)&quot;">​</a></h2><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to &quot;✨ New Features&quot;">​</a></h3><ul><li>One-click thumbnail display from toolbar icon</li><li>Direct thumbnail display on YouTube video pages</li><li>Thumbnail View showing all resolutions and formats</li><li>Support from maximum quality (maxresdefault) to low quality</li><li>Support for both JPG and WebP formats</li><li>YouTube Shorts thumbnail support</li></ul><h3 id="🎨-ui-ux" tabindex="-1">🎨 UI/UX <a class="header-anchor" href="#🎨-ui-ux" aria-label="Permalink to &quot;🎨 UI/UX&quot;">​</a></h3><ul><li>Simple and intuitive popup design</li><li>Fast thumbnail loading</li><li>One-click download capability</li></ul><h3 id="🔒-privacy" tabindex="-1">🔒 Privacy <a class="header-anchor" href="#🔒-privacy" aria-label="Permalink to &quot;🔒 Privacy&quot;">​</a></h3><ul><li>No data storage design</li><li>Real-time processing only</li><li>Open source code publication</li></ul><h3 id="🌐-supported-browsers" tabindex="-1">🌐 Supported Browsers <a class="header-anchor" href="#🌐-supported-browsers" aria-label="Permalink to &quot;🌐 Supported Browsers&quot;">​</a></h3><ul><li>Google Chrome</li><li>Microsoft Edge</li><li>Brave</li><li>Other Chromium-based browsers</li><li>Firefox (planned)</li></ul><hr><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><p>Planned features:</p><ul><li>[ ] Official Firefox support</li><li>[ ] Batch thumbnail download</li><li>[ ] Custom thumbnail size specification</li><li>[ ] Enhanced thumbnail preview features</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Feedback</p><p>Feel free to submit feature requests and bug reports on <a href="https://github.com/mosunset/youtube_watch_thumbnails/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p></div>',18)])])}const m=e(t,[["render",r]]);export{p as __pageData,m as default};
